<template>
  <section><div class="catalog-heading"><div><p class="eyebrow">AI 问答管理</p><h1>问答记录</h1><p class="muted">正文与来源已脱敏。查看详情会留审计；删除或过期的正文不可读取。</p></div></div><form class="records-filters" @submit.prevent="page = 1; load()"><select v-model="filters.ownerKind" aria-label="咨询身份"><option value="">全部身份</option><option value="BUYER">买家</option><option value="GUEST">访客</option></select><select v-model="filters.scene" aria-label="咨询场景"><option value="">全部场景</option><option v-for="scene in scenes" :key="scene" :value="scene">{{ aiSceneLabel(scene) }}</option></select><select v-model="filters.status" aria-label="回答状态"><option value="">全部状态</option><option v-for="status in statuses" :key="status" :value="status">{{ aiStatusLabel(status) }}</option></select><label>更新开始<input v-model="filters.from" type="date"></label><label>更新结束<input v-model="filters.to" type="date"></label><label>买家ID<input v-model="filters.buyerId" type="number" min="1" placeholder="不限买家"></label><label>关键词<input v-model.trim="filters.keyword" maxlength="100" placeholder="搜索脱敏正文"></label><select v-model="filters.helpful" aria-label="回答反馈"><option value="">全部反馈</option><option value="true">有帮助</option><option value="false">没帮助</option></select><button class="secondary-button">查询</button></form><PageStatus :loading="loading" :error="error" :empty="!items?.items.length" empty-text="当前筛选范围内暂无问答记录。" @retry="load" />
    <div v-if="items?.items.length" class="table-scroll"><table class="admin-table"><thead><tr><th>对话</th><th>身份</th><th>提问数</th><th>最新状态</th><th>更新</th><th>操作</th></tr></thead><tbody><tr v-for="item in items.items" :key="item.id"><td>{{ item.title }}</td><td>{{ item.ownerKind === 'BUYER' ? '买家 #' + item.buyerId : '访客' }}</td><td>{{ item.questionCount }}</td><td>{{ aiStatusLabel(item.status) }}</td><td>{{ date(item.updatedAt) }}</td><td><button type="button" class="text-action" @click="detail(item.id)">查看脱敏详情</button></td></tr></tbody></table><PagePagination :page="page" :size="items.size" :total="items.total" @change="changePage" /></div>
    <section v-if="selected || detailLoading || detailError" class="editor-section"><div class="catalog-heading"><h2>{{ selected?.title ?? '对话详情' }}</h2><button type="button" class="text-action" @click="selected = null; detailError = ''">收起</button></div><PageStatus :loading="detailLoading" :error="detailError" @retry="detail(lastId)"/><template v-if="selected"><div class="record-messages"><article v-for="item in selected.messages" :key="item.id"><header><strong>{{ item.role === 'USER' ? '用户' : '鲜果AI' }}</strong><span>{{ date(item.createdAt) }}</span><span v-if="item.status">{{ aiStatusLabel(item.status) }}</span></header><p>{{ item.content || '本次回答没有正文' }}</p><small v-if="item.errorMessage">{{ item.errorMessage }}</small><small v-if="item.helpful !== null">当前反馈：{{ item.helpful ? '有帮助' : '没帮助' }} {{ item.feedbackReason ?? '' }}</small><details v-if="item.sources.length"><summary>来源快照</summary><div v-for="(source, index) in item.sources" :key="index"><strong>{{ source.title }} · {{ source.version ? '版本' + source.version : source.type }}</strong><p>{{ source.excerpt }}</p></div></details></article></div><h3>回答尝试与模型记录</h3><div class="table-scroll"><table class="admin-table"><thead><tr><th>尝试</th><th>结果</th><th>模型 / 来源</th><th>时延</th><th>Usage</th><th>终态原因</th></tr></thead><tbody><tr v-for="attempt in selected.attempts" :key="attempt.id"><td>#{{ attempt.id }}<small>{{ attempt.retryOf ? '重试 #' + attempt.retryOf : '首次尝试' }}</small></td><td>{{ aiStatusLabel(attempt.status) }}<small>{{ aiSceneLabel(attempt.scene) }}</small></td><td>{{ attempt.model ?? '基础查询' }}<small>{{ attempt.configId ? '配置 v' + attempt.configId : '无在线配置' }} · {{ attempt.mode ?? '—' }} · {{ attempt.retrievalMode ?? '—' }}</small></td><td>{{ attempt.totalMs === null ? '无样本' : attempt.totalMs + 'ms' }}<small>首内容 {{ attempt.firstContentMs === null ? '无样本' : attempt.firstContentMs + 'ms' }}</small></td><td>{{ attempt.promptTokens ?? '—' }} / {{ attempt.completionTokens ?? '—' }}<small>输入 / 输出Token</small></td><td>{{ attempt.errorCode ?? '—' }}</td></tr></tbody></table></div><details v-if="selected.ruleHits.length"><summary>规则命中摘要 · {{ selected.ruleHits.length }} 条</summary><p v-for="(hit, index) in selected.ruleHits" :key="index">{{ hit.stage }} · 规则 #{{ hit.ruleId }} v{{ hit.version }} · {{ hit.summary }}</p></details></template></section>
  </section>
</template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import PageStatus from '../components/PageStatus.vue'
import PagePagination from '../components/PagePagination.vue'
import { errorMessage, type Page } from '../api/catalog'
import { listRecords, getRecord, aiSceneLabel, aiStatusLabel, type RecordSummary, type RecordDetail } from '../api/admin-ai'
const filters = reactive({ ownerKind: '', scene: '', status: '', from: '', to: '', buyerId: '', keyword: '', helpful: '' }), page = ref(1), items = ref<Page<RecordSummary> | null>(null), loading = ref(false), error = ref(''), selected = ref<RecordDetail | null>(null), detailLoading = ref(false), detailError = ref(''), lastId = ref(0)
const scenes = ['GENERAL', 'PRODUCT', 'RECOMMEND', 'ORDER', 'AFTER_SALE'], statuses = ['ACCEPTED', 'RUNNING', 'COMPLETED', 'DEGRADED', 'FAILED', 'CANCELLED', 'BLOCKED']
let detailVersion = 0
const date = (value: string) => new Date(value).toLocaleString('zh-CN', { hour12: false })
async function load() { loading.value = true; error.value = ''; try { items.value = await listRecords({ page: page.value, ...Object.fromEntries(Object.entries(filters).filter(([, value]) => value)) }) } catch (failure) { detailVersion++; items.value = null; selected.value = null; error.value = errorMessage(failure) } finally { loading.value = false } }
function changePage(value: number) { page.value = value; void load() }
async function detail(id: number) { const version = ++detailVersion; lastId.value = id; detailLoading.value = true; detailError.value = ''; selected.value = null; try { const record = await getRecord(id); if (version === detailVersion) selected.value = record } catch (failure) { if (version === detailVersion) detailError.value = errorMessage(failure) } finally { if (version === detailVersion) detailLoading.value = false } }
onMounted(load)
</script>
<style scoped>
.records-filters{display:flex;gap:12px;flex-wrap:wrap;align-items:end;margin:22px 0}.records-filters select,.records-filters input{font:inherit;font-size:12px;padding:9px;border:1px solid #d7e1d1;border-radius:5px;background:white}.records-filters label{display:grid;gap:5px;font-size:10px;color:#7d8c73}.record-messages{max-width:850px}.record-messages article{border-bottom:1px solid #e4ecdc;padding:17px 0}.record-messages header{display:flex;gap:15px;font-size:10px;color:#95a08b}.record-messages strong{font-size:12px;color:#49633f}.record-messages p{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px;line-height:1.9}.record-messages small,.admin-table small{display:block;color:#8a987e;font-size:10px;line-height:1.8;margin-top:5px}details{margin:15px 0;font-size:12px;line-height:1.9;color:#7c8e6e}details>div{padding:10px 15px;border-left:2px solid #d5e2c8;margin-top:10px}h3{margin:30px 0 15px;font-size:15px}.admin-table td{max-width:270px;overflow-wrap:anywhere}@media(max-width:700px){.records-filters select{flex:1;min-width:120px}.record-messages header{flex-wrap:wrap;gap:8px}}
</style>
